import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"辅助数据结构","link":"/api/SIMD-API/basic_api/aux_data_structures/aux_data_structures"},{"text":"UnaryRepeatParams","link":"/api/SIMD-API/basic_api/aux_data_structures/UnaryRepeatParams"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/aux_data_structures/UnaryRepeatParams.md","filePath":"api/SIMD-API/basic_api/aux_data_structures/UnaryRepeatParams.md","lastUpdated":1787050286000}'),l={name:"api/SIMD-API/basic_api/aux_data_structures/UnaryRepeatParams.md"};function t(e,s,r,i,d,_){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>UnaryRepeatParams<span id="ZH-CN_TOPIC_0000001487959374"></span></h1><p>UnaryRepeatParams为用于控制操作数地址步长的数据结构。结构体内包含操作数相邻迭代间相同DataBlock的地址步长，操作数同一迭代内不同DataBlock的地址步长等参数。</p><p>相邻迭代间的地址步长参数说明请参考<a href="../memory_vector_compute/SIMD_compute/high_dim_split.html#%E5%9C%B0%E5%9D%80%E9%97%B4%E9%9A%94%E9%85%8D%E7%BD%AE">repeatStride</a>；同一迭代内DataBlock的地址步长参数说明请参考<a href="../memory_vector_compute/SIMD_compute/high_dim_split.html#%E5%9C%B0%E5%9D%80%E9%97%B4%E9%9A%94%E9%85%8D%E7%BD%AE">dataBlockStride</a>。</p><p>结构体具体定义为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">DEFAULT_BLK_NUM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">DEFAULT_BLK_STRIDE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">DEFAULT_REPEAT_STRIDE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>

<span class="k">struct</span><span class="w"> </span><span class="nc">UnaryRepeatParams</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="nf">UnaryRepeatParams</span><span class="p">()</span><span class="w"> </span><span class="p">{}</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="nf">UnaryRepeatParams</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStrideIn</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcBlkStrideIn</span><span class="p">,</span>
<span class="w">        </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">dstRepStrideIn</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">srcRepStrideIn</span><span class="p">)</span>
<span class="w">        </span><span class="o">:</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="p">(</span><span class="n">dstBlkStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">srcBlkStride</span><span class="p">(</span><span class="n">srcBlkStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">dstRepStride</span><span class="p">(</span><span class="n">dstRepStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">srcRepStride</span><span class="p">(</span><span class="n">srcRepStrideIn</span><span class="p">)</span>
<span class="w">    </span><span class="p">{}</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="nf">UnaryRepeatParams</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStrideIn</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcBlkStrideIn</span><span class="p">,</span>
<span class="w">        </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">dstRepStrideIn</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">srcRepStrideIn</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">halfBlockIn</span><span class="p">)</span>
<span class="w">        </span><span class="o">:</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="p">(</span><span class="n">dstBlkStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">srcBlkStride</span><span class="p">(</span><span class="n">srcBlkStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">dstRepStride</span><span class="p">(</span><span class="n">dstRepStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">srcRepStride</span><span class="p">(</span><span class="n">srcRepStrideIn</span><span class="p">),</span>
<span class="w">          </span><span class="n">halfBlock</span><span class="p">(</span><span class="n">halfBlockIn</span><span class="p">)</span>
<span class="w">    </span><span class="p">{}</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockNumber</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_BLK_NUM</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_BLK_STRIDE</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcBlkStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_BLK_STRIDE</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">dstRepStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_REPEAT_STRIDE</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">srcRepStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_REPEAT_STRIDE</span><span class="p">;</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">repeatStrideMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">strideSizeMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">halfBlock</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="p">};</span>
</code></pre></div><p>其中，blockNumber，repeatStrideMode，strideSizeMode为保留参数，用户无需关心，使用默认值即可。halfBlock表示CastDequant指令的结果写入对应Unified Buffer（UB）的上半（halfBlock = true）还是下半（halfBlock = false）部分。用户需要自行定义DataBlock Stride参数，包含dstBlkStride，srcBlkStride，以及Repeat Stride参数，包含dstRepStride，srcRepStride。</p></article></div>`,1)])])}const k=a(l,[["render",t]]);export{o as __pageData,k as default};
